import java.io.*;

public class Main {
    static byte[] buf = new byte[1 << 16];
    static int len = 0, ptr = 0;
    static InputStream in = System.in;

    static int read() throws IOException {
        if (ptr == len) { len = in.read(buf, 0, buf.length); ptr = 0; if (len <= 0) return -1; }
        return buf[ptr++];
    }

    static long nextLong() throws IOException {
        int c = read();
        while (c != '-' && (c < '0' || c > '9')) c = read();
        boolean neg = c == '-';
        if (neg) c = read();
        long r = 0;
        while (c >= '0' && c <= '9') { r = r * 10 + c - '0'; c = read(); }
        return neg ? -r : r;
    }

    static int nextInt() throws IOException { return (int) nextLong(); }

    static String next() throws IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        if (c == -1) return null;
        ByteArrayOutputStream sb = new ByteArrayOutputStream();
        while (c != -1 && c > ' ') { sb.write(c); c = read(); }
        return sb.toString(java.nio.charset.StandardCharsets.UTF_8);
    }

    public static void main(String[] args) throws IOException {
        int n = nextInt();
        String[] a = new String[n];
        for (int i = 0; i < n; i++) a[i] = next();
        double[] p = new double[n];
        double best = Double.MAX_VALUE;
        for (int i = 0; i < n; i++) {
            int[] cnt = new int[65536];
            int mx = 0;
            for (int j = 0; j < a[i].length(); j++) mx = Math.max(mx, ++cnt[a[i].charAt(j)]);
            p[i] = (double) mx / a[i].length();  // share of the most common character
            best = Math.min(best, p[i]);
        }
        boolean[] other = new boolean[65536];
        for (int i = 0; i < n; i++)
            if (p[i] != best)
                for (int j = 0; j < a[i].length(); j++) other[a[i].charAt(j)] = true;
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < n; i++)
            if (p[i] == best)
                for (int j = 0; j < a[i].length(); j++)
                    if (!other[a[i].charAt(j)]) sb.append(a[i].charAt(j));
        System.out.println(sb);
    }
}

package main

import (
	"bufio"
	"fmt"
	"os"
)

var rd = bufio.NewReaderSize(os.Stdin, 1<<20)

func readInt() int {
	n := 0
	c, _ := rd.ReadByte()
	for c == ' ' || c == '\n' || c == '\r' || c == '\t' {
		c, _ = rd.ReadByte()
	}
	neg := c == '-'
	if neg {
		c, _ = rd.ReadByte()
	}
	for c >= '0' && c <= '9' {
		n = n*10 + int(c-'0')
		c, _ = rd.ReadByte()
	}
	if neg {
		return -n
	}
	return n
}

func readToken() string {
	c, err := rd.ReadByte()
	for err == nil && (c == ' ' || c == '\n' || c == '\r' || c == '\t') {
		c, err = rd.ReadByte()
	}
	if err != nil {
		return ""
	}
	b := []byte{}
	for err == nil && !(c == ' ' || c == '\n' || c == '\r' || c == '\t') {
		b = append(b, c)
		c, err = rd.ReadByte()
	}
	return string(b)
}

func main() {
	n := readInt()
	a := make([]string, n)
	for i := range a {
		a[i] = readToken()
	}
	p := make([]float64, n)
	best := 2.0
	for i, s := range a {
		var cnt [256]int
		mx := 0
		for j := 0; j < len(s); j++ {
			cnt[s[j]]++
			mx = max(mx, cnt[s[j]])
		}
		p[i] = float64(mx) / float64(len(s)) // share of the most common character
		best = min(best, p[i])
	}
	var other [256]bool
	for i, s := range a {
		if p[i] != best {
			for j := 0; j < len(s); j++ {
				other[s[j]] = true
			}
		}
	}
	out := []byte{}
	for i, s := range a {
		if p[i] == best {
			for j := 0; j < len(s); j++ {
				if !other[s[j]] {
					out = append(out, s[j])
				}
			}
		}
	}
	fmt.Println(string(out))
}
